import{_ as e,c as t,o as i,ag as r}from"./chunks/framework.Bw-5EFTY.js";const u=JSON.parse('{"title":"Fluent Affiliate Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started/fluent-affiliate-glossary.md","filePath":"guide/getting-started/fluent-affiliate-glossary.md","lastUpdated":1756116278000}'),o={name:"guide/getting-started/fluent-affiliate-glossary.md"};function n(s,a,l,h,d,f){return i(),t("div",null,a[0]||(a[0]=[r('<h1 id="fluent-affiliate-glossary" tabindex="-1">Fluent Affiliate Glossary <a class="header-anchor" href="#fluent-affiliate-glossary" aria-label="Permalink to &quot;Fluent Affiliate Glossary&quot;">​</a></h1><p>This glossary defines common terms used throughout the FluentAffiliate documentation to help you understand key features and concepts.</p><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><h3 id="affiliate" tabindex="-1">Affiliate <a class="header-anchor" href="#affiliate" aria-label="Permalink to &quot;Affiliate&quot;">​</a></h3><p>An individual who signs up to promote your products or services. They share a unique link and earn a commission when a customer purchases through that link.</p><h3 id="affiliate-area-portal" tabindex="-1">Affiliate Area/Portal <a class="header-anchor" href="#affiliate-area-portal" aria-label="Permalink to &quot;Affiliate Area/Portal&quot;">​</a></h3><p>A dedicated page on your website that serves as the main portal for your affiliates. From here, they can log in to their dashboard to generate referral links, track their visits and payouts, and access important information.</p><h3 id="affiliate-dashboard" tabindex="-1">Affiliate Dashboard <a class="header-anchor" href="#affiliate-dashboard" aria-label="Permalink to &quot;Affiliate Dashboard&quot;">​</a></h3><p>The central hub inside the Affiliate Area, where an affiliate can manage all their activities. It provides key performance metrics like total earnings, pending commissions, total referrals, and conversion rates.</p><h3 id="affiliate-group" tabindex="-1">Affiliate Group <a class="header-anchor" href="#affiliate-group" aria-label="Permalink to &quot;Affiliate Group&quot;">​</a></h3><p>A feature that allows you to organize affiliates into different tiers, each with its specific commission rate and settings. You can assign any affiliate to a group to apply that group&#39;s rate.</p><h3 id="affiliate-management" tabindex="-1">Affiliate Management <a class="header-anchor" href="#affiliate-management" aria-label="Permalink to &quot;Affiliate Management&quot;">​</a></h3><p>The section in the admin dashboard where you can get an overview of all your affiliates, manage their status (e.g., Active, Pending, Inactive), and manually add new ones.</p><h2 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h2><h3 id="branded-coupon-code" tabindex="-1">Branded Coupon Code <a class="header-anchor" href="#branded-coupon-code" aria-label="Permalink to &quot;Branded Coupon Code&quot;">​</a></h3><p>A feature that allows tracking affiliate commissions through unique discount codes instead of traditional referral links. It integrates with e-commerce plugins (like WooCommerce or EDD), allowing an administrator to create a standard coupon and assign it to a specific affiliate using a dedicated field provided by Fluent Affiliate. When a customer uses the code, they receive a discount, and the assigned affiliate is automatically credited with a commission for the sale.</p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><h3 id="commission" tabindex="-1">Commission <a class="header-anchor" href="#commission" aria-label="Permalink to &quot;Commission&quot;">​</a></h3><p>The payment an affiliate earns for a successful referral. The commission can be set as a Flat fixed amount or a Percentage of the sale price.</p><h3 id="conversion" tabindex="-1">Conversion <a class="header-anchor" href="#conversion" aria-label="Permalink to &quot;Conversion&quot;">​</a></h3><p>An event that occurs when a visitor clicks an affiliate&#39;s link and completes a purchase or a desired action. A successful conversion results in a referral.</p><h3 id="currency" tabindex="-1">Currency <a class="header-anchor" href="#currency" aria-label="Permalink to &quot;Currency&quot;">​</a></h3><p>The type of money (e.g., USD, EUR) in which affiliate commissions will be paid. This is configured in the Referral Settings.</p><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><h3 id="dashboard-admin" tabindex="-1">Dashboard (Admin) <a class="header-anchor" href="#dashboard-admin" aria-label="Permalink to &quot;Dashboard (Admin)&quot;">​</a></h3><p>The main overview screen for you, the site administrator, within the FluentAffiliate plugin. It gives you a clear and simple view of your entire affiliate program, showing key stats like total payouts, earnings, referrals, and visits in one place.</p><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><h3 id="email-settings-admin" tabindex="-1">Email Settings (Admin) <a class="header-anchor" href="#email-settings-admin" aria-label="Permalink to &quot;Email Settings (Admin)&quot;">​</a></h3><p>A settings area where the site administrator can customize the email notifications sent to both admins and affiliates. You can configure the sender name and email, and edit the subject and body of notifications for events like new affiliate registrations or new referrals.</p><h2 id="f" tabindex="-1">F <a class="header-anchor" href="#f" aria-label="Permalink to &quot;F&quot;">​</a></h2><h3 id="flat-rate" tabindex="-1">Flat Rate <a class="header-anchor" href="#flat-rate" aria-label="Permalink to &quot;Flat Rate&quot;">​</a></h3><p>A type of commission where an affiliate earns a fixed amount for each referral, no matter the total purchase price. For example, you can set a flat commission of $10 for every sale.</p><h2 id="i" tabindex="-1">I <a class="header-anchor" href="#i" aria-label="Permalink to &quot;I&quot;">​</a></h2><h3 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to &quot;Integrations&quot;">​</a></h3><p>The ability for FluentAffiliate to connect and work seamlessly with other popular WordPress plugins. This allows you to track affiliate commissions from e-commerce stores (like WooCommerce), course platforms (like LearnDash), and form builders (like FluentForms).</p><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><h3 id="license-key" tabindex="-1">License Key <a class="header-anchor" href="#license-key" aria-label="Permalink to &quot;License Key&quot;">​</a></h3><p>A unique code you receive when you purchase FluentAffiliate. Activating your license key in the settings is required to get access to plugin updates and premium support.</p><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><h3 id="migrator-settings" tabindex="-1">Migrator Settings <a class="header-anchor" href="#migrator-settings" aria-label="Permalink to &quot;Migrator Settings&quot;">​</a></h3><p>A feature that allows you to manage data migration and cleanup tasks for your FluentAffiliate data.</p><h3 id="multi-domain-management" tabindex="-1">Multi-Domain Management <a class="header-anchor" href="#multi-domain-management" aria-label="Permalink to &quot;Multi-Domain Management&quot;">​</a></h3><p>A feature that lets you track affiliate sales, referrals, and commissions across multiple websites from a single, centralized dashboard.</p><h2 id="n" tabindex="-1">N <a class="header-anchor" href="#n" aria-label="Permalink to &quot;N&quot;">​</a></h2><h3 id="notification-settings-affiliate" tabindex="-1">Notification Settings (Affiliate) <a class="header-anchor" href="#notification-settings-affiliate" aria-label="Permalink to &quot;Notification Settings (Affiliate)&quot;">​</a></h3><p>An option in the affiliate&#39;s settings panel that allows them to enable or disable email notifications for new referrals.</p><h2 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h2><h3 id="onboarding" tabindex="-1">Onboarding <a class="header-anchor" href="#onboarding" aria-label="Permalink to &quot;Onboarding&quot;">​</a></h3><p>A simple, step-by-step setup guide that appears after you first install FluentAffiliate. It helps you configure the most important settings right away, though you can also skip the steps and set them up later.</p><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><h3 id="payment-email-affiliate" tabindex="-1">Payment Email (Affiliate) <a class="header-anchor" href="#payment-email-affiliate" aria-label="Permalink to &quot;Payment Email (Affiliate)&quot;">​</a></h3><p>A field in the affiliate&#39;s settings where they can add or update their PayPal email address to receive their commission payouts.</p><h3 id="payout" tabindex="-1">Payout <a class="header-anchor" href="#payout" aria-label="Permalink to &quot;Payout&quot;">​</a></h3><p>The action of sending earned commissions to your affiliates. FluentAffiliate helps you track and record these payments manually and generate reports, but it does not automatically send money through payment gateways.</p><h3 id="payout-management" tabindex="-1">Payout Management <a class="header-anchor" href="#payout-management" aria-label="Permalink to &quot;Payout Management&quot;">​</a></h3><p>A section in the admin dashboard for managing affiliate payments. While payments must be made manually, this area lets you record each transaction, generate a detailed report of who was paid, and export the report for your records.</p><h3 id="percentage-rate" tabindex="-1">Percentage Rate <a class="header-anchor" href="#percentage-rate" aria-label="Permalink to &quot;Percentage Rate&quot;">​</a></h3><p>A type of commission where an affiliate earns a percentage of the total purchase price for each referral. For example, you can set a commission of 10% on every sale made through an affiliate&#39;s link.</p><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><h3 id="referral" tabindex="-1">Referral <a class="header-anchor" href="#referral" aria-label="Permalink to &quot;Referral&quot;">​</a></h3><p>A record that is created every time an affiliate successfully brings in a sale or conversion through their unique affiliate link. You can view and manage all referrals from your admin dashboard.</p><h3 id="referral-management" tabindex="-1">Referral Management <a class="header-anchor" href="#referral-management" aria-label="Permalink to &quot;Referral Management&quot;">​</a></h3><p>The section in the admin dashboard that provides tools to manage and track all affiliate referrals. It allows you to filter referrals by status (Unpaid, Paid, Rejected), search for specific ones, and edit or delete them.</p><h3 id="referral-settings" tabindex="-1">Referral Settings <a class="header-anchor" href="#referral-settings" aria-label="Permalink to &quot;Referral Settings&quot;">​</a></h3><p>The section in the admin dashboard where you can set the global, site-wide rules for how commissions are calculated. This includes the default commission rate, rate type, and currency.</p><h3 id="referral-url-generator" tabindex="-1">Referral URL Generator <a class="header-anchor" href="#referral-url-generator" aria-label="Permalink to &quot;Referral URL Generator&quot;">​</a></h3><p>The tool available in an affiliate&#39;s dashboard that allows them to create a unique referral link for any page or product on your site. They paste the desired page URL, and the generator automatically creates their unique affiliate link to copy and share.</p><h3 id="referral-variable" tabindex="-1">Referral Variable <a class="header-anchor" href="#referral-variable" aria-label="Permalink to &quot;Referral Variable&quot;">​</a></h3><p>The keyword in your affiliate URLs that is used for tracking. For example, if you set the variable as ref, a referral link will look like yoursite.com/product?ref=username.</p><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><h3 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h3><p>A label that shows the current state of a referral, payout, or affiliate. Common statuses include Paid, Unpaid, Pending, Rejected, and Active.</p><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><h3 id="terms-conditions-page" tabindex="-1">Terms &amp; Conditions Page <a class="header-anchor" href="#terms-conditions-page" aria-label="Permalink to &quot;Terms &amp; Conditions Page&quot;">​</a></h3><p>A dedicated page on your site that outlines the rules of your affiliate program. You can select this page in the General Settings, and affiliates must agree to these terms during registration.</p><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h2><h3 id="visits" tabindex="-1">Visits <a class="header-anchor" href="#visits" aria-label="Permalink to &quot;Visits&quot;">​</a></h3><p>A log of every click an affiliate receives on their affiliate links. This allows affiliates to see which of their promotional links are being clicked, if those clicks led to a sale, and when the click happened.</p>',78)]))}const m=e(o,[["render",n]]);export{u as __pageData,m as default};
